import csv,collections
bom=collections.defaultdict(lambda: collections.defaultdict(list))
for r in csv.DictReader(open('/app/kits/kit-bom.csv')):
    bom[r['kit']][r['effective_from']].append((r['component'],int(r['qty'])))
def comps(kit,date):
    revs=[d for d in bom[kit] if d<=date]
    return bom[kit][max(revs)]
def explode(sku,q,date,req,kits):
    if sku in bom:
        kits.add((sku,date))
        for c,n in comps(sku,date): explode(c,q*n,date,req,kits)
    else: req[sku]+=q
lines={}
dates={}
for r in csv.DictReader(open('/app/kits/open-orders.csv')):
    k=(r['order'],r['line']);dates[r['order']]=r['created']
    if k not in lines or int(r['amendment'])>lines[k][0]: lines[k]=(int(r['amendment']),r['sku'],int(r['qty']),r['status'])
sub={('KT-10','CP-202'):('CP-213',1),('KT-10','CP-203'):('CP-214',2),('KT-20','CP-204'):('CP-218',1)}
res=collections.defaultdict(lambda: collections.defaultdict(int))
pick=collections.defaultdict(lambda: collections.defaultdict(int))
main=collections.defaultdict(lambda: collections.defaultdict(int))
def R(o,s,q): res[o][s]+=q
def allr(o,skus,q):
    for s in skus.split(): R(o,'CP-'+s,q)
allr('SO-5501','201 202 203 204 205 211',3)
allr('SO-5501','201 203 204 205 211',-1); main['SO-5501']['CP-213']=1
allr('SO-5502','201 202 203 204 205 211',2)
for s,q in [(217,4),(216,4),(215,2),(209,2)]: R('SO-5503','CP-%d'%s,q)
main['SO-5503']['CP-216']=2
for s,q in [(217,4),(216,4),(215,2),(211,2),(209,2),(208,1),(207,2),(205,4),(204,3),(203,2),(202,2),(201,2)]: R('SO-5504','CP-%d'%s,q)
R('SO-5504','CP-215',-1);R('SO-5504','CP-201',-1);main['SO-5504']['CP-218']=2
for s,q in [(208,3),(207,6),(205,4),(204,3)]: R('SO-5505','CP-%d'%s,q)
allr('SO-5506','212 207 206 205 204 203 202 201',2)
allr('SO-5507','201 202 203 204 205 211',1); allr('SO-5507','201 202 203 205 211',-1); R('SO-5507','CP-204',-1); main['SO-5507']['CP-218']=1
for s,q in [(208,4),(207,8),(204,4)]: R('SO-5508','CP-%d'%s,q)
R('SO-5508','CP-207',-5)
allr('SO-5509','212 206 205 204 203 202 201',2); allr('SO-5509','212 206 205 204 202 201',-1); main['SO-5509']['CP-214']=2
for s,q in [(217,2),(216,2),(215,1)]: R('SO-5510','CP-%d'%s,q)
allr('SO-5510','212 209 206 205 204 203 202 201',1)
for s,q in [(208,2),(207,4),(204,2)]: R('SO-5511','CP-%d'%s,q)
R('SO-5511','CP-207',-2);R('SO-5511','CP-208',-1);R('SO-5511','CP-204',-1)
for s,q in [(208,1),(207,2),(204,1)]: R('SO-5512','CP-%d'%s,q)
# reserved picks as picked
resp={}
resp['SO-5501']=dict.fromkeys(['CP-201','CP-203','CP-204','CP-205','CP-211'],1)
resp['SO-5504']={'CP-215':1,'CP-201':1}
resp['SO-5507']=dict.fromkeys(['CP-201','CP-202','CP-203','CP-205','CP-211'],1)
resp['SO-5508']={'CP-207':5}
resp['SO-5509']=dict.fromkeys(['CP-212','CP-206','CP-205','CP-204','CP-202','CP-201'],1)
resp['SO-5511']={'CP-207':2,'CP-208':1,'CP-204':1}
out=[];adj=[]
for o in sorted(dates):
    d=dates[o];req=collections.defaultdict(int);kits=set()
    for (oo,l),(a,s,q,st) in lines.items():
        if oo==o and st!='cancelled': explode(s,q,d,req,kits)
    pk=collections.defaultdict(float)
    for s,q in resp.get(o,{}).items(): pk[s]+=q
    for s,q in main[o].items():
        done=False
        for (k,_) in kits:
            for c,n in comps(k,d):
                if sub.get((k,c),(None,))[0]==s and not done:
                    pk[c]+=q/sub[(k,c)][1]; done=True
        if not done:
            if s in req or s not in [x for k in sub.values() for x in k[:1]]: pk[s]+=q
    for s in sorted(set(req)|set(res[o])):
        t=max(0,req[s]-pk[s]); cur=res[o][s]
        out.append((o,s,req[s],pk[s],t))
        if t!=cur: adj.append((o,s,t-cur))
with open('/app/kit-reservations.csv','w') as f:
    f.write('order,sku,required,picked,reserved\n')
    for o,s,r,p,t in out: f.write(f'{o},{s},{r},{p:g},{t:g}\n')
for a in adj: print(a)
